import Blog from "../pages/blog";
import { graphql } from "gatsby";

export default Blog;

export const pageQuery = graphql`query TemplateTagPage($tag: String) {
  # Get tags
  tags: allMarkdownRemark(filter: {frontmatter: {draft: {ne: true}}}) {
    group(field: {frontmatter: {tags: SELECT}}) {
      fieldValue
      totalCount
    }
  }

  # Get posts
  posts: allMarkdownRemark(
    sort: {frontmatter: {createdDate: DESC}}
    filter: {frontmatter: {draft: {ne: true}, tags: {in: [$tag]}}, fileAbsolutePath: {regex: "/blog/"}}
  ) {
    totalCount
    edges {
      node {
        html
        timeToRead
        fields {
          slug
        }
        frontmatter {
          tags
          title
          updatedDate(formatString: "DD MMMM, YYYY")
          image {
            childImageSharp {
              gatsbyImageData(layout: FIXED, width: 700, height: 100)
            }
          }
          author {
            jsonId
            bio
            avatar {
              childImageSharp {
                gatsbyImageData(layout: FIXED, width: 35, height: 35)
              }
            }
          }
        }
      }
    }
  }
}`;
